INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1029575-math102', 'stk-user7238', 'MATH 102', 'info', '{"desc": "الكورس بشكل عام عن التكامل\nينقسم تقريباً لـ3 اقسام\n\nالاول عن تعريف التكامل بالنهايات وطريقه تكامل بعض الدوال وثم تطبيقات عليها (شابتر 5و6)\n\nالثاني وهو الاهم وهو طرق التكامل(اربع طرق اساسيه)شابتر 7\nوهذا القسم لازم تفهمه عدل وحاول تحل اكبر قدر من الاسئله عليه\nلان اغلب الكورسات الثانيه تحتاجه(ماث201 بشكل مبسط وماث 202 بشكل اكبر)\n\nالقسم الثالث وهو السيريز(المتسلسلات)-شابتر 11\nبدايه الماتيرال غريبه شوي بس مع التركيز وفهم الفكره بتلاقيه سهل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/2", "user": "user7238", "ts": 1335614683000, "tid": 120612, "pn": 2}}', 1335614683000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1029587-math102', 'stk-vip_master', 'MATH 102', 'info', '{"desc": "من أجمل كورسات الماث ان كان مع مدرس محترم او الطالب جلس على اليوتوب مع الدكتور بترك جلسة محترمة\nالكورس أغلبه عن التكامل و ما هو شرط انه يكون الطالب على معرفة مسبقة بها\nيقدر يبدا من جديد و يأسس من جديد و يتستمع بالمادة .\nالي يفكر يأجل دراستها او يجمع كم درس فوق بعض\nاقوله على الكورس السلام", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/3", "user": "VIP_Master", "ts": 1335616092000, "tid": 120612, "pn": 3}}', 1335616092000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1030365-math102', 'stk-s2010xxxxx', 'MATH 102', 'info', '{"desc": "كووورس ممتع الى ابعد حد … ويعتمد شوي على اشياء درستها بالتحضيريه من الفاكتورنق ,والساين والكوساين , بشكل عام الكورس حلو … واذا ذاكرت اول باول بيكون سهل ان شا الله … وانصح الجميع بالمذاكره من الكتاب لانه مفيد جدا … والتمارين حقته حلوه … ذاكر كل سكشن مع التمارين الفرديه وان شا الله راح تكون مريت اغلب الافكار 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/4", "user": "s2010xxxxx", "ts": 1335740195000, "tid": 120612, "pn": 4}}', 1335740195000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1046183-math102', 'stk-user6966', 'MATH 102', 'info', '{"desc": "جودة المقرر بشكل عام\n\nمقرر مهم وطبيعي أي شخص مهتم بالعلوم يدرس التكامل لكثرة تطبيقاتها في الحياة. تقديري له جيدا جدا.\n\nالمواضيع التي يغطيها المقرر\n\nالمقرر يغطي بشكل خاص عن التكامل , ثم بعد ذلك في نهاية المقرر يتحدث عن المتسلسلات والمتتابعات الحسابية.\n\nالكتاب المستخدم للمقرر\n\nسيء جداً جداً جداً جداً جداً + مُمل!!!!!!\nكتاب سيء لأبعد حدود , لما رحت لمكتبة جرير واطّلعت على كتاب التكامل المُقدم من PEARSON , وجدت أستاذ !! وليس فقط كتاب . كتاب جداً رائع ومنسق وملوّن بطريقة تفتح النفس , كما أن في نهاية كل مثال , refer للأسألة المشابهة له في الـ Problems . هذا غير الوضوح التام في الأمثلة.\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nبصراحة الـ Syllabus جداً سيء , وأسألة الهومورك Infinite !! مليار سؤال الهومورك , وهذا أشوفه جداً سلبي بشأن الطالب. والأمثلة كما ذكرت أعلا سيئة جداً بسبب سوء الكتاب.\n\nمدى فائدته في الناحية التطبيقية\n\nالتكامل مفيدة جداً في كثير من نواحي الحياة , وكثير من كورسات الجامعة تعتمد على التكامل ( مثل مادة الـ Economics وكذلك كورسات الـ Stat ولا أعلم عن الهندسة ولكني متأكد أنهم يستعملون التكامل لبعض النظريات لديهم .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/5", "user": "user6966", "ts": 1338128457000, "tid": 120612, "pn": 5}}', 1338128457000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1050298-math102', 'stk-brav3', 'MATH 102', 'info', '{"desc": "السلام عليكم و رحمة الله و بركاته.\n\nSemester 112.\n\nجودة المقرر بشكل عام:\n\nممتازة.\n\nالمواضيع التي يغطيها المقرر :\n\n1- مشكلة الـ Area و الـ Distance.\n\n2- تعريف الـ Definite Integral كـ Infinite Limit للـ Riemann Sum.\n\n3- The Fundamental Theorem Of Calculus بشقيها.\n\n4- الـ Indefinite Integral كـ Anti-Derivative و الـ Net Change Theorem.\n\n5- الـ Substitution Rule.\n\n6- إيجاد المساحة بين المنحنيات.\n\n7- إيجاد الحجوم باستخدام الـ Disk-Washer Method أو الـ Cylindrical Shells Method.\n\n8- حساب الـ Average لـ Function.\n\n9- الـ Integration By Parts.\n\n10- الـ Trigonometric Integrals.\n\n11- الـ Trigonometric Substitution.\n\n12- Technique الـ Partial Fractions Decomposition لـ Integrating Rational Functions.\n\n13- الـ Improper Integrals.\n\n14- الـ Infinite Sequences و Divergenceـها أو Convergenceـها.\n\n15- الـ Infinite Series و Divergenceـها أو Convergenceـها و الـ Tests For Divergence Or Convergence.\n\n16- The Integral Test و الـ Estimates Of Sums.\n\n17- الـ Comparison Test و الـ Limit Comparison Test.\n\n18- الـ Alternating Series.\n\n19- الـ Absolute Or Conditional Convergence و الـ Ratio Test و الـ Root Test.\n\n20- الـ Power Series و Interval Of Convergenceـها و الـ Radius Of Convergenceـها.\n\n21- تحويل الـ Functions لـ Power Series .\n\n22- تايلور Series و ماكلارين Series.\n\n23- إيجاد طول خط منحني.\n\n24-إيجاد مساحة سطح Revolutionary Surface.\n\nالكتاب المستخدم للمقرر:\n\nممتاز.\n\nالأسئلة والأمثلة المستخدمة في المقرر:\n\nتميل إلى اختبار الـ Techniques الرياضية بدلاً من اختبار الفهم (و هو الأهم).\n\nمدى فائدته في الناحية التطبيقية:\n\nمفيد 100%.\n\nملاحظات:\n\n1- إذا كنت عند مدرس سيء ، لا تجعله سبب للإهمال و اليأس ، الرياضيات لا تحتاج إلى مدرس ، بل تحتاج إلى مصدر جيد للدراسة ، و الكثير من التمرن.\n\n2- لا تجعل صعوبة الاختبارات سبب للإهمال و اليأس ، كثرة التمرن و الممارسة ستحول هذه الصعوبة إلى سهولة مفرطة.\n\n3- ضع جل اهتمامك في فهم الموضوع فهماً جيداً لأن فهم الموضوع هو ما يحدد قدرتك على حل المسائل الرياضية من عدمها.\n\n4- اجعل هدفك من دراسة الرياضيات الفائدة لنفسك ، فالفهم الجيد للرياضيات سيفيدك في كل نواحي حياتك.\n\nمع السلامة.\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/6", "user": "BRAV3", "ts": 1338766998000, "tid": 120612, "pn": 6}}', 1338766998000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1051427-math102', 'stk-user4492', 'MATH 102', 'info', '{"desc": "ياليت الكتب كلها نفس كتاب الـ Calculus ❤️ ❤️ ❤️\nإضافة : في هذا الكورس خصّيصاً … مستحيل تفهمه 100% إلا بحل مسااااااائل كثيييييرة ،\nوكل ما كثّرت مسائل كل ماقرّبت من A+ 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/8", "user": "user4492", "ts": 1338891828000, "tid": 120612, "pn": 8}}', 1338891828000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1052528-math102', 'stk-satellite_ise', 'MATH 102', 'info', '{"desc": "مسائل مفيدة للتمرس قبل الاختبار النهائي لماث102\n\nهذا الكورس يعتمد على التمرس الكثير وحل المسائل وكثيرا ما يعتمد على تطبيق قواعد التكامل والمتسلسلات والمتتابعات وتطبيقات التكامل المحدد من المساحات والحجوم الدورانية ،،\n\nوفي المرفقات مجموعة أسئلة من اعداد الدكتور ابراهيم الرصاصي ،،\n\nحلك لهذه الاسئلة وفهمها يعطيك خبرة كافية للتعامل مع اي اسئلة غدارة 😆", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/9", "user": "satellite_ISE", "ts": 1339133263000, "tid": 120612, "pn": 9}}', 1339133263000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1231795-math102', 'stk-guest', 'MATH 102', 'info', '{"desc": "ماث 102 من أجمل وامتع كورسات الماث بالنسبة لي، لا أراه صعب على الاطلاق بشرط أنك تشتغل شغل محترم على الكورس ، القسم اعتمد كتاب جديد لماث 101 + 102 هو كتاب Thomas cal في رأيي الكتاب غير جيد في الشرح لكن التمارين في نهاية كل سكشن ممتازة أيضا استفدت من نوت الحميدي بشكل كبير وفي سؤال جاه بالفاينل من النوت بنفس الارقام 🤠 ،جزئية المساحة والحجم اذا لم تفهما من مدرسك أنصح بشدة بالاستفادة من الشيخ باتريك في اليوتيوب شرح جبار، السيريز أو المتسلسلات يبغالها حل أسئلة كثيييييييير عشان تتقنها ، لا تضيع ميجر 2 من يدك لأنه ريتن والأفكار فيه متكررة من الأولد اكزام بكثرة\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/11", "user": "Guest", "ts": 1370348548000, "tid": 120612, "pn": 11}}', 1370348548000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1232480-math102', 'stk-user8577', 'MATH 102', 'info', '{"desc": "الكورس كله في كفة و متيريال الفاينال في كفة آخرى … السيريز مو صعبة بس يحتاج لها تدريب كثير و انت تكون في آخر الترم والمواد كلها بدأت تصعب … فنصيحة حاول تشد في اول اختبارين عشان تساعدك في الأخر.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/12", "user": "user8577", "ts": 1370545740000, "tid": 120612, "pn": 12}}', 1370545740000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1232487-math102', 'stk-user8713', 'MATH 102', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nMath 102 term 122\nالدكتور أسان لو\nالكتاب Thomas ''s calculus\n\nمواضيع المقرر\n\nالميجر الأول\nالتكامل و تطبيقاته و متسلسلات غير منتهية\nفي البداية تعريف التكامل المحدد و كيف تجيب المساحة اللي تحت المنحنى\nو بعدين تتعلم ثلاث طرق لإيجاد حجم الأجسام الدورانية و كيف توجد طول الدالة\n\nالميجر الثاني\nتوجد مساحة الأجسام الدورانية ثم تأخذ تعريف الدالة اللوغارتمية كتكامل و اشتقاقها و اشتقاق الدالة الأسية\nبعدين تأخذ دوال القطع الزائد hyperbolic function ( اللي كانت في 101 في الكتاب القديم ) تعريفها و اشتقاقها\nو اشتقاق الدالة العكسية لها derivative of inverse of hyperbolic function بعدية تأخذ طرق التكامل\n\nالنهائي\nالتكامل للدوال غر المتصلة و التكامل المحدد إلى مالا نهاية ثم تدخل في وحدة المتسلسلات\nتأخذ عدة إختبارات لتحديد هل المتسلسلة متقاربة أو متباعدة و فقط اختبارين تقدر توجد القيمة اللي تتقارب لها المتسلسلة\nو اختبارين توجد القيمة التقرببية بعدين تأخذ 4 دروس ركز فيها جاء عليها 6 أسئلة في النهائي\n\nملاحظات :\nلم أعاني أي صعوبة في هذا المقرر و هذا يرجع إلى أمور\n1- أني أحب الرياضيات حب الرضيع لمحالب أمه\n2- كنت في الأجازة بين الفصلين 121 و 122 أحل تكاملات على أني بدخل مسابقة في التكامل\nطبعا اذا صرت محترف في التكامل ف الميجر الأول و الثاني بيدك 50% ما علي إلا تذاكر النهائي صح\n3- القسم كان ما يجيب مسائل صعبة بل يجيب سهلة\n4- أسان لو دكتور ليس له مثيل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/13", "user": "user8713", "ts": 1370547518000, "tid": 120612, "pn": 13}}', 1370547518000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1366641-math102', 'stk-user9766', 'MATH 102', 'info', '{"desc": "أخبث كورس مر علي في الجامعة…\nالدرجات تطير فيه بسهولة…\n\nانتبه لنفسك من الأول قبل ما تنصدم في المياجر والفاينل…\n\n+ الكورس يحتاج مدرّس شرّيح + خبير… ما ينفع سلف ستدي…\n\nأحب أيضاً أنوّه على ان نوت بدر الحميدي ممتازة جداً…\n\nأعتقد لو تاخذ الكورس مع شوقي أو الحميدي أو يعقوب شحاتة… أمورك طيبة من ناحية المدرس…\n\nالباقي عليك!\n\n+ لا تتوقع ان الأسئلة بتجي مشابهة كثير للأولد اقزام…\n\nيعتمد هذا الكورس على (أساسياتك في الماث - فهمك للكونسبت) … ثم يجي بعدها التدريب…\n\nبخلاف الكورسات اللي قبله أحس ممكن تمشي بحل كثير من المسائل حتى لو ما كنت مستوعب الكونسبت مضبوط…\n\nكورس صعب؟… إي, صعب جداً … مستحيل؟ لا, للي بيعطيه حقه من البداية…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/20", "user": "user9766", "ts": 1400446000000, "tid": 120612, "pn": 20}}', 1400446000000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1366665-math102', 'stk-practice', 'MATH 102', 'info', '{"desc": "بالنسبة لي , اصعب من 101\n\nترى الكورس مو هين , ولو استهنت فيه لو شوية بتاكلها على راسك علطول\n\nوبالنسبة للصيف , احسن شي انك تاخده صيف لانه بيكون لحاله وبتركز عليه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/26", "user": "Practice", "ts": 1400449081000, "tid": 120612, "pn": 26}}', 1400449081000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1366866-math102', 'stk-user7795', 'MATH 102', 'info', '{"desc": "بالنسبة لي أخذت فيه أسوأ قريد من دخلت الجامعة\n\nيحتاج تدريب وأصعب من ١٠١ بمراحل\n\nذاكر من الكتاب وحل الodd numbers كلها لأن أسئلة الهوموورك ما تكفي\n\nركز على الميجر الثاني وفهمه زين لأنه تقريبا هو أسهل متيريال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/28", "user": "user7795", "ts": 1400493451000, "tid": 120612, "pn": 28}}', 1400493451000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1367197-math102', 'stk-alnuaimi', 'MATH 102', 'info', '{"desc": "من ناحيتي كان من أمتع وأفضل كورسات الماث اللي خذتها بالجامعة\nما أزيد على كلام الاخوان و لكن هذا الكورس يبغاله اهتمام من ناحية المذاكرة اليومية وحل أسئلة الكتاب و الاولد اقزام\nو أيضا المدرس له الاثر الكبير بعد الله سبحانه و تعالى\nأنا كنت مع الدكتور بدر الحميدي 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/29", "user": "AlNuAiMi", "ts": 1400530374000, "tid": 120612, "pn": 29}}', 1400530374000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1367205-math102', 'stk-ahmad-ali', 'MATH 102', 'info', '{"desc": "الكورس ممتع جداً والتكاملات مثل الالغاز! مستغرب من التقييم وبالنسبة لي كان اسهل من الـ101\nطبعا اخر شابتر معروف انه الاصعب بلا منازع وهذا سبب صعوبة الفاينل\nالكورس سهل وممتع للي يحب التكامل ويفهم الكونسبت", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/30", "user": "ahmad-ali", "ts": 1400531720000, "tid": 120612, "pn": 30}}', 1400531720000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1367500-math102', 'stk-conan14', 'MATH 102', 'info', '{"desc": "من أمتع كورسات الماث على مدى الحياة !!!\n\nالكورس كله حلو ما عدا آخر جزء اللي هو الـ Series 🤪\n\nنصيحة لكل واحد ،، نزلها مع دكتور ممتاز ومتمكن من الكورس عشان تفهم الكونسبت صح ويتبقى لك التطبيق فقط …\n\nعن نفسي أخذتها مع أفضل دكتور ماث في نظري … الدكتور فيصل فيرق ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/31", "user": "Conan14", "ts": 1400588892000, "tid": 120612, "pn": 31}}', 1400588892000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1369127-math102', 'stk-i_love_science', 'MATH 102', 'info', '{"desc": "رأيي الشخصي\n\nكورس كريه جدا\nاصعب من 101 بكثيييييييييييير\nنظام تذاكر قبل المياجر والفاينل مستحيل تطلع بقريد اعلى من +d وغالبا حتاخذ f قد وجهك\nحل الاسئلة يحتاج تفكير وذكاء واهم شي يحتاج حل تمارين كثييير عشان الافكار مالها نهاية\nيعني قريدك يعتمد بشكل اساسي على كم سؤال اتدربت وحليته قبل المياجر والفاينل\nالدكاترة الي يدرسو الكورس للأمانة اغلبهم مستواهم ممتاز جدا ،\nلكن مهما يكون يظل الثقل الاكبر على المياجر والفاينل …\nيعني محا يفرق معاك الدكتور ذاك الفرق غير في التصحيح للميجر الرتن وبس\n\nانا انسان طول عمري احب الماث الين جيت لهذي الجامعة كرهت امي في الماث\nوهذا الكوس هو الاسوء على الاطلاق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/32", "user": "I_love_science", "ts": 1400763972000, "tid": 120612, "pn": 32}}', 1400763972000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1369632-math102', 'stk-undefined', 'MATH 102', 'info', '{"desc": "الكورس هذا امتع كورس مر علي بالجامعة حتى اللحظة للامانة اذا عطيته حقه يعطيك حقك\nواخذت الكورس مع الدكتور احمد شوقي الله يحفظة ويطول عمره الكورس هذا ماراح انساه ان شاء الله ماحييت", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/33", "user": "Undefined", "ts": 1400829998000, "tid": 120612, "pn": 33}}', 1400829998000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1369636-math102', 'stk-ieren', 'MATH 102', 'info', '{"desc": "132\nالكورس سههل جدا جدا للي يذاكر اسئلة الكتاب كلها واولد اكزام واجد … ضيعت الميجرين وضمنت الرسوب لكن ركزت على اسئلة الكتاب وطلعت بقريد ماكنت متوقعه ابد على العموم الناس تشكي من السيرييس والصراحة كان اسهل واحلى جزء …انصح لهذا الكورس بعبدالاله قادري 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/34", "user": "iEreN", "ts": 1400830379000, "tid": 120612, "pn": 34}}', 1400830379000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1371896-math102', 'stk-medoalkebsi', 'MATH 102', 'info', '{"desc": "كورس ممتع مممتع ممتع جدآ , سمعت انه صعب , لكن جبت فيه اعلى درجه في كورساتي\n\nبالماث كلها . ومثل ما قال الاخ\niEreN\n\nالاستاذ عبدالاله قادري ممبدع جدآ في الكورس هذا.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/39", "user": "Medoalkebsi", "ts": 1401094747000, "tid": 120612, "pn": 39}}', 1401094747000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1372364-math102', 'stk-user8581', 'MATH 102', 'info', '{"desc": "جودة المقرر بشكل عام\nمن احلى الكورسات الي درستها . صج.تحس انك قاعد تدرس ماث مب بس تعويض في قوانين\n\nالمواضيع التي يغطيها المقرر\nhttp://skfupm.kfupm.edu.sa/vb/showpost.php?p=1034748&postcount=6\n\nالكتاب المستخدم للمقرر & الأسئلة والأمثلة المستخدمة في المقرر\nhttp://images.pearsoned-ema.com/jpeg/large/9780321636324.jpg\nكنوعية اسئلة وتمارين اشوفه رائع …لكن كشرح للكونسبت اشوفه عادي واحيانا يطول السالفة وهي قصيرة …الاسئلة مفيدة بشكل كبير …حاول تحلهم لأنه اكثر من سؤال في المياجر جاء من اسئلة الكتاب مع شوية تعديلات بسيطة …فأنتبه من هالشي ونفس الوقت هالكورس يحتاج حل وتدريب كثير عكس 101 … حل اسئلة قد ماتقدر واضمنك لك B+ على الاقل في هالكورس\n\n+\nحاول تنزل مع دكتور شرحه ممتاز ومتعاون + لاتعتمد بشكل كلي على الدكتور … الدكتور راح يوفر عليك الوقت في فهم الكونسبت والي يكون باقي عليك هو حل الاسئلة والتدريب …\n\nبالنسبة الي يبي ينزله في الصيف : انصحه مايخلي الدروس تتراكم ويوميا يحل اسئلة الكتاب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/40", "user": "user8581", "ts": 1401146777000, "tid": 120612, "pn": 40}}', 1401146777000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1373546-math102', 'stk-abo-da7m', 'MATH 102', 'info', '{"desc": "الفصل 132\nجودة المقرر بشكل عام\n\nممتاز\n\nالمواضيع التي يغطيها المقرر\n\nالتكامل … أساليب وطرق للتكامل … تطبيقات لحساب الحجم … المتتابعات و المتسلسلات\n\nالكتاب المستخدم للمقرر\n\nThomas Calculus 12th\n\nما أشوفه جيد مرة بالشرح وأفضل الكتاب السابق، الجيد فيه الأسئلة نهاية كل سكشن\n\n+ فيه قسم أسمه Theory and examples بالأسئلة حله مفيد جدا ويساعدك تفهم بشكل أفضل\n\nمدى فائدته في الناحية التطبيقية\nمفيد جدا وله تطبيقات غير منتهية بالعلوم والهندسة\n\n-------------------------------\n* أنصح بحل عدد كبير من الاختبارات السابقة بفترات متقطعة طول الفصل - عشان تكتسب مهارة - موب قبل المياجر تحل كل شي بسرعة .\n\n* حاول تفهم الكونسبت بشكل أعمق اذا بغيت فل مارك لأن بيجي سؤال سؤالين بالكونسبت ولا لها علاقة بمهارتك بالحل .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/41", "user": "abo-da7m", "ts": 1401310884000, "tid": 120612, "pn": 41}}', 1401310884000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1375197-math102', 'stk-abu_hamad_22', 'MATH 102', 'info', '{"desc": "انا من وجهة نظري آشوف هذا الكورس آحلى بكثيييير من 101\n\nهذا الكورس ميزته آفهم الكونسبت و حل آكبر قدر من المسائل و الافكار\n\nالتكامل بشكل عام هو عبارة عن آلغاز . لازم تشغل مخك يعني ما في قانون و طبّق\n\nو الجزء الغثيث هو ماتيريال الفاينل حق السيريس … اما جزء التكامل جداً مُمتع\n\nانا آنصح بآسئلة الكتاب\n\nالكتاب ثم الكتاب ثم الكتاب ثم الكتاب ثم الكتاب ثم قبل الميجر بكم يوم طق لك كم آولد آقزامز و آضمن لك بآذن الله ما تقل عن +b\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/43", "user": "Abu_Hamad_22", "ts": 1401595515000, "tid": 120612, "pn": 43}}', 1401595515000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1422634-math102', 'stk-user9534', 'MATH 102', 'info', '{"desc": "كورس جميل 🥰 مع إني أكره الماث 😆\n\nالمهم حل اسئلة الكتاب (طبعا مهب كلها … تلقى بالسيلبس أرقامها) وطبعا موجود المانوال سلوشن هن بالمنتدى عشان تتأكد من حلك 🤠\n\nطبعا فيه اشياء كثير مافهمتها ولكن باتريك ماقصر ❤️ 🥰\nhttp://patrickjmt.com/\nانزل تحت عند الكالكولس ودور اسم الموضوع اللي مافهمته وخش الفيديو وان شاء الله تفهم 🌹\n\nطبعا فيه أغلب كورسات الماث … أذا مافهمت منه اكتب اسم الدرس باليوتيوب وبتلقى ناس غيره 😏\n\nالمهم في هذا الكورس الكتاب + أولد اكزام 😆\n\nبالتوفيق 🤴", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/44", "user": "user9534", "ts": 1422321889000, "tid": 120612, "pn": 44}}', 1422321889000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1424125-math102', 'stk-madridista', 'MATH 102', 'info', '{"desc": "الكورس ممتع، لكنه طوييييل… في الفاينل لما تجي تذاكر الدروس الأولى تحس إنك اخذتها الترم الماضي.\nأيضاً الكورس صعب وشبه مستحيل تطلع بقريد اعلى من c+ اذا ماتدربت وحليت أكبر عدد ممكن من المسائل.\nانا بدخل هالسنه سفمور ومدري إذا يحق لي احكم ولالا الان لكن هالكورس هو اصعب كورس لي إلى الآن مع فزكس 101 .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/45", "user": "Madridista", "ts": 1439787890000, "tid": 120612, "pn": 45}}', 1439787890000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1449575-math102', 'stk-m_nd_m', 'MATH 102', 'info', '{"desc": "جودة المقرر بشكل عام\nجودته ممتازة كورس مفيد و مهم تفهمه زين… بكل صراحة كورس ممتع خصوصا شابتر 7 <----- الانتجريشن\n\nالمواضيع التي يغطيها المقرر\nشابتر 5: افتتاحية لكالكولاس 2 و شرح مبسط للي بتشوفه بعدين بالكورس (شابتر غثيث شوي)\nشابتر 6: Volumes & Areas و دربس بسيط (شابتر حلو لكن يحتاج فهم عميق و حذر)\nشابتر 7: Integration Technics (أحلى شابتر… ممتع جدًا)\nشابتر 8: Arc length & Surface Area (شابتر كيوت و حليوة)\nشابتر 11: Series (يحتاج فهم و استيعاب كبيرين… خصوصا إذا جاتك أسئلة نوعا ما نظرية)\n\nالكتاب المستخدم للمقرر\n\nالأسئلة والأمثلة المستخدمة في المقرر\nوالله ما فتحت الكتاب 🙂 كله من النوتة حقت الرصاصي و الأسئلة اللي حاطها\n\nمدى فائدته في الناحية التطبيقية\nمهم جدًا و سبق و ذكرت هذه النقطة فوق… الديفرنشيشن و الانتجريشن لهم تطبيقات كثيرة <----- فزكس 101 أفضل مثال (Work Force Velocity…Etc)\n\nنوتة الرصاصي:\nMATH 102 - NOTES | طھط­ظ…ظٹظ„\n***الرجاء إخباري في حالة عدم عمل الملف\n\nالسيلابس:\nNew Page 1\n\nباختصار… كورس منفوخ… لا تسوون غلطتي و تدخلون بعقلية “الكورس طويل و صعب”… بسبة هالعقلية أنا معرض إني أطلع بقريد مااشششش<----- تبًا للصورة النمطية !", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/48", "user": "M_nd_m", "ts": 1463607489000, "tid": 120612, "pn": 48}}', 1463607489000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1449582-math102', 'stk-rygart', 'MATH 102', 'info', '{"desc": "كورس منفوخ جدا !!\n\nانا لقيته اسهل من ماث 101 بكثييييير .\n\nمدري ممكن علشاني منزله مع الرصاصي\n\nالمهم ماني مقيم الكورس التقييم كفى ووفى الأخ اللي فوقي .\n\nاللي عليك تسويه بالكورس هذا هو :\n1: تذاكر من نوتات الرصاصي اللي رافعها الاخ فوق ، اذا ما اشتغل الرابط راسلني او راسله و برفعها لكم …\n2- اذا خلصت النوته حل كل الاسئلة بأخر النوته من 3-7 اسئلة ، حلها بفهم أغلبها أفكار حلوة و اولد اقزام .\n3- حل الاسئلة اللي محدده بالسلبس .\n4- في دروس الانتقريشن “شابتر7” حاول تحل اخر عشرة اسئلة من كل درس و 7.1-7.5 .\n* نفس الوضع في السيريز “شابتر11” حل اخر عشرة اسئلة من كل درس 11.2-11.7\n5- لآ لآ لآ لآ لآ تحط براسك ان الكورس صعب و بتشوف انه سهل بنفسك !\nهو بس بعض الدروس في شابتر7 و شابتر 11 لازم تحل اسئلة كثير .\n\nو بالتوفيق لكم 😕", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/49", "user": "Rygart", "ts": 1463610615000, "tid": 120612, "pn": 49}}', 1463610615000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1450099-math102', 'stk-mkd', 'MATH 102', 'info', '{"desc": "مشكلة أغلب الطلاب ياخذون نوتات وما يفتحون الكتاب وبيون قريد خرافي\n\nخصوصا بهذا الكورس أنت تحتاج الكتاب بشكل مرعب . الكتاب هنا هو صديقك الصدوق 😏 سهل الفهم وفيه أمثله كثيرة\n\nكورس مظلوم بمعنى الكلمة . سمعنا إنه صعب ومدري وشو وطلع خرابيط . اللي يفرق إنك تحتاج تحل مسائل أكثر حبتين فقط لا أقل ولا أكثر 🙄\n\nأجمل كورس ماث خذته وأتوقع هو أجمل كورس ماث بالجامعة كلها\n\nلو تذاكر أول باول وتحل أسئلة الكتاب وكم أولد اقزام قبل المياجر والفاينل = أمووووورك بالسليم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/50", "user": "MKD", "ts": 1464012346000, "tid": 120612, "pn": 50}}', 1464012346000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1466647-math102', 'stk-user10578', 'MATH 102', 'info', '{"desc": "الكورس جميل و أفضل من 101 بكثير\nعيبه انه طويل و الشابتر الاخير غثيث شوي\nراح تلاحظ بالكورس ان يتدرج بالصعوبة ( او تصير المواضيع ادسم )\nيعني ميتريال الميجر الاول سهلة جداً ، الميجر الثاني تقدر تقول ادسم شوي لكنه امتع ، ميتريال الفاينل راح تغطي 50% من الـseries وهذي غثيثة شوي يبغالها متابعة و فهم .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/52", "user": "user10578", "ts": 1484906735000, "tid": 120612, "pn": 52}}', 1484906735000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1467357-math102', 'stk-walo0od', 'MATH 102', 'info', '{"desc": "Term 161\n\nجودة المقرر بشكل عام\nممتاز ويغطي التكامل + المتسلسلات بشكل كامل وممتاز.\nالمواضيع التي يغطيها المقرر\n\n- شابتر 5: مقدمة إلى المتكاملة (integral)\n* المساحات والمسافات وبداية تعريف الintegral بواسطة الlimits.\n* تعريف الdefinite integral (اللي تكون لها نهايتين فوق وتحت).\n* القاعدة الأساسية للتفاضل والتكامل (F.T.C).\n* تعريف الindefinite integral + قاعدة التعويض (Substitution Rule).\n- شابتر 6: تطبيقات على المتكاملات\n* حساب المساحة بين منحنيين.\n* الأحجام.\n* الأحجام بطريقة الصدفة الاسطوانية.\n* القيمة المتوسطة لدالّة.\n- شابتر 7: استراتيجيات لإيجاد المتكاملات\n* integration by parts (التكامل بالأجزاء) - لما يكون عندك integral مكونة من دالتين مضروبة في بعض.\n* تكامل الدوال المثلثية.\n* تعويض الدوال المثلثية.\n* تكامل الدوال الRational (ما أعرف ترجمتها :)) عن طريق الكسور الجزئية.\n* المتكاملات الغير صحيحة.\n- شابتر 8: تطبيقات زيادة على المتكاملات\n* طول القوس.\n* مساحة سطح الدوران.\n- شابتر 11: المتسلسلات واختبارات لإيجاد هل هي متقاربة أو منحرفة\n* Sequences.\n* Series.\n* اختبار المتكاملة.\n* اختبارات المقارنة.\n* المتسلسلة المترددة (بين الموجب والسالب).\n* المتسلسلات الأسيّة وتمثيلها كدوال.\n* Taylor and Maclurin Series.\n\nالكتاب المستخدم للمقرر\nCalculus: Early Transcendentals - 7th Edition by James Stewart\nنفس الكتاب المستخدم لماث 101 و 201\nالأسئلة والأمثلة المستخدمة في المقرر\n--\nمدى فائدته في الناحية التطبيقية\nمفيد جداً ويعطيك خبرة جيدة في التعامل مع التكامل ويربطه ربط جميل بالتفاضل.\nإضافات\nالمادة ممتعة إلى أبعد حد على عكس Math 101 إلي ممكن تكون صعبة لأنها البداية.\nالكورس هذا يحتاج منك متابعة أوّل بأوّل مع دكتورك + تحل مسائل الكتاب (مهمة جداً) وصدقني الA+ بيدك.\nلا تستهين في الكورس بس في نفس الوقت استمتع فيه وحاول تحل مسائل قد ما تقدر (بعض الأسئلة في الاختبارات جات زي اللي في الكتاب تماماً).\nفي Online Video Course على البلاكبورد من شرح الدكتور بدر الحميدي - رائعة جداً وراح تفيدك إذا ما فهمت شي.\n\nبالتوفيق واستمتع بالكورس 😆.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/53", "user": "Walo0od", "ts": 1485855967000, "tid": 120612, "pn": 53}}', 1485855967000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1474050-math102', 'stk-abdullah2015', 'MATH 102', 'info', '{"desc": "أخذت المادة ترم 162\n\nجودة المقرر بشكل عام:\n\nممتازة جدًا، كورس ممتع.\n\nالمواضيع التي يغطيها المقرر:\n\n- شابتر 5 مقدمة للIntegration.\n- شابتر 6 فيه Applications of Integration.\n- شابتر 7 عبارة عن Integration Techniques … بتغطي في هذا الشابتر عدة طرق للIntegration مثل الIntegration by parts و Trig Substitution وPartial fractions (الكسور الجزئية) وغيرهم، الشابتر الأمتع بعد السيريز بالنسبة لي.\n- شابتر 8 فيه Applications of Integration (يختلف عن شابتر 6 إن هنا بتأخذ تطبيقات ثانية بتحتاج فيها الIntegration Techniques اللي درستهم في شابتر 7).\n- وأخيراً شابتر 11 اللي يتكلم عن الـ Series (وهو أمتع شابتر بالنسبة لي).\n\nالكتاب المستخدم للمقرر:\n\nكتاب جدًا ممتاز.\n\nالأسئلة والأمثلة المستخدمة في المقرر:\n\nأسئلة الكتاب معقولة وممتازة.\n\nمدى فائدته في الناحية التطبيقية\nالمقرر مفيد ومهم جدًا لكل مهندس مهما كان تخصصه، تطبيقات التكامل داخلة في كل شيء. وكذلك مفيد ومهم جدًا لكورسات الماث اللي بعده 201 و202 .\n\nإضافات:\n\n1- صعوبة المادة هذي تختلف من شخص إلى آخر، البعض حبها وبدأ يفهمها من البداية والبعض ما دخلت عقله بسهولة، على سبيل المثال، أنا هنا ألاحظ أغلب الردود يقولون إن جزء السيريز غثيث وصعب وما يدخل العقل وجزء التكامل أسهل نسبيًا، لكن اللي صار لي العكس، على الرغم من إني طالب A+ في الماث إلا إني كنت أواجه صعوبة في فهم دروس الIntegration وما بديت أهضم الIntegration إلا بعد فترة، بعكس دروس السيريز اللي شفت إنها جدًا ممتعة وسهلة أكثر من الIntegration. فأمر الصعوبة والسهولة نسبي وبقوة، لكن بشكل عام إذا كان مستواك ممتاز في الكورسات اللي قبل ممتاز راح تقدر تعدي هذا الكورس بسلام + بالجد والاجتهاد كل شيء يصير سهل.\n\n2- بالنسبة لي أشوف المادة أصعب من MATH 101 بكثير وتحتاج Practice كثير.\n\n3- الدكتور مهم جدًا في هذا الكورس، حاول تنزل مع دكتور ممتاز لأنه مب زي 101 تقدر تمشي حالك سيلف ستدي.\n\n4- الخلاصة إن هذا الكورس إما بيكون أحلى كورس تأخذه أو أسوأ كابوس ممكن تشوفه في حياتك، أنت تقرر.\n\nبالتوفيق للجميع 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/54", "user": "Abdullah2015", "ts": 1496062812000, "tid": 120612, "pn": 54}}', 1496062812000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1493624-math102', 'stk-ahm2d1', 'MATH 102', 'info', '{"desc": "Term 172 With R.Anabosi\n\nالكورس بشكل عام وسط ، في البدايه بيكون سهل وبعدها بيبدا يثقل شوي شوي .\n\nيتكلم عن Integral و Area و Sequence و Series\n\nاصعب شيء بالنسبه لي دروس ال Volume كانت شوي غير واضحه .\n\nما ينفع تنزله مع جدول ثقيل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/55", "user": "Ahm2d1", "ts": 1528039845000, "tid": 120612, "pn": 55}}', 1528039845000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1504528-math102', 'stk-to_be_engineer', 'MATH 102', 'info', '{"desc": "Term 172\n\nبالنسبة لي كان أمتع من Math 101 وطلعت بقريد افضل .\n\nالمواضيع اللي يغطيها الكورس ممتعة وماهي صعبة ولها تطبيقات كثيرة جدا خاصة في الفيزيكس وبعضكم أخذ فيزيكس 101 ويعرف هالشي. الكورس اشوفه عبارة عن كورسين لأنك في البداية بتأخذ التكامل بأنواعه وتطبيقاته (الجزء الامتع بالنسبة لي) ، و بتمسك خط لين اخر ثلاث اسابيع بتبدأ شي جديد اللي هو المتسلسلات وعن نفسي ما كنت مستمتع والسبب واحد من اثنين : فيا لانه كان نهاية السمستر و جزء المتسلسلات دسم شوي او لانه ما جازلي ، ما اذكر بالضبط لكن لعله كان مزيج بين الاثنين. المتسلسلات ما بلعتها بس فهمتها بسهوله لكن السكشن الاخير هو اللي كان غثيث بكل ما تعنيه الكلمه كنت اعتبره تشابتر لحاله لكن حفظت طريقة حل الاسئلة اللي تجي عليه ومشت الامور ولله الحمد.\n\nكيف تضمن أنك تجيب A\" ِat least\" ؟\n\nخذها قاعدة في أي كورس ماث لازم بداية السمستر تجهز لك نوتة شاملة و اولد اقزام سكشن باي سكشن للتمرين وقبل الإختبار وافتح الموقع وحل اختبارين كاملة اقل شي واحد بدون ما تفكر بالوقت والثاني بظروف الاختبار.\n\nبالنسبة للنوته اللي استخدمتها وأشوفها أفضل نوته مرت علي من ماث 001 الى ماث 201 هي نوتة الدكتور الغني عن التعريف عبدالإله قادري لأنها تتدرج معك من المستوى السهل الى الافكار الثقيلة اللي ممكن تجي في الميجر … مليااانه افكاروالدكتور تعب عليها.\n\nالنوته :\nDropbox - Notes (kadri) - Simplify your life\n\nإذا قدرت تسجل مع الدكتور بترتاح كثير.\n\nاولد اقزام سكشن باي سكشن من مجهود الدكتور ياسر خالد الله يجزاه خير :\nDropbox - Old Exams Section by Section - Simplify your life\n\nبالتوفيق…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/56", "user": "To_Be_Engineer", "ts": 1546692848000, "tid": 120612, "pn": 56}}', 1546692848000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518467-math102', 'stk-abofordan2004', 'MATH 102', 'info', '{"desc": "ترم 191\n\nالكورس بكل صراحة سهل ويمديك حتى لو انت طالب افرج تجيب فيه قريد عالي بس عليك متابعته اول باول\n\nطبعا الماتيريال كله سهل بغض النظر عن شابتر11 الاخير ( series and sequences ) طبعا مو ذيك الصعوبة ولكنه غثيث ومذاكرته تاخذ وقت بس اذا فهمته صح بتشوف انه سهل\n\nانت بس خذ الكونسبت من فيديوهات البلاك بورد بعدها روح على نوتات محسن الشهراني وامورك في السليم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/57", "user": "AboFordan2004", "ts": 1577709782000, "tid": 120612, "pn": 57}}', 1577709782000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1522354-math102', 'stk-nasalmz', 'MATH 102', 'info', '{"desc": "من امتع وأجمل الكورسات الماث اللي خذيتهن، لأن فيه تفكير وتشغيلة مخ.\n\nمن بعد التجربة فيه بعض النقاط ودي اذكرها:\n\nنوت الأستاذ محسن هي الزبدة في 102.\nاحفظ “general form” حقت بعض المسائل لأنها بتختصر لك الوقت حييل.\nالأولد اقزام لا تنساه.\nاسئلة الكتاب جبارة في تشابتر 7 واحتمالية انهم يجيبون سؤال بالرقم في ميجر 2 او الفاينل عالية جدا.\nانتبه يا عزيزي تخلي الكورس يتراكم لأنك بتعمل شاي.\nوبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-102-calculus-ii/120612/58", "user": "Nasalmz", "ts": 1590419659000, "tid": 120612, "pn": 58}}', 1590419659000, 1794315553, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
